def semver_sort(versions):
    def parse(v):
        # strip build metadata
        main_part = v.split('+', 1)[0]
        if '-' in main_part:
            core, prerelease = main_part.split('-', 1)
        else:
            core, prerelease = main_part, None
        major, minor, patch = (int(x) for x in core.split('.'))
        if prerelease is None:
            pre_ids = None
        else:
            ids = prerelease.split('.')
            pre_ids = []
            for ident in ids:
                if ident.isdigit():
                    pre_ids.append((0, int(ident)))
                else:
                    pre_ids.append((1, ident))
        return (major, minor, patch, pre_ids)

    def key(v):
        major, minor, patch, pre_ids = parse(v)
        has_no_prerelease = 1 if pre_ids is None else 0
        pre_tuple = tuple(pre_ids) if pre_ids is not None else ()
        return (major, minor, patch, has_no_prerelease, pre_tuple)

    return sorted(versions, key=key)

